public static boolean isOvenReady(int temperature) {
    boolean isReady;
    if (temperature >= 150 && temperature <= 250) {
        isReady = true;
    } else {
        isReady = false;
    }
    return isReady;
}

public static double calculateBusTicketPrice(int age) {
    double ticketPrice = 3.0;
    if (age < 12 || age > 65) {
        return ticketPrice;
    } else {
        ticketPrice = ticketPrice + 2;
        return ticketPrice;
    }
}

public static double calculateProductDiscount(double price, boolean onlineOrder) {
    double discount = 0.0;
    if (onlineOrder == true) {
        if (price > 100.0) {
            discount = 5.0;
        }
    } else {
        discount = 5.0;
    }
    return discount;
}

public static int calculateChargingTimeMinutes(int initialBatteryLevel) {
    int minutesPassed = 0;
    int fullChargeLevel = 100;
    int batteryLevel = initialBatteryLevel;
    while (true) {
        if (batteryLevel >= fullChargeLevel) {
            break;
        } else if (batteryLevel <= 80) {
            batteryLevel = batteryLevel + 2;
            minutesPassed = minutesPassed + 1;
        } else if (batteryLevel > 80) {
            batteryLevel = batteryLevel + 1;
            minutesPassed = minutesPassed + 1;
        }
    }
    return minutesPassed;
}

public static int largestNumber(int[] numbers) {
    int largest = numbers[0];
    int i = 0;
    boolean isNegative = false;
    while (i < numbers.length && isNegative == false) {
        if (numbers[i] < 0) {
            isNegative = true;
        }
        if (numbers[i] >= 0 && numbers[i] > largest) {
            largest = numbers[i];
            continue;
        }
        i++;
    }
    return largest;
}

public static boolean isEligibleForBonus(int[] homeworkGrades, boolean exemption) {
    int bonusPoints = 0;
    for (int i = 0; i < homeworkGrades.length; i++) {
        if (exemption == false) {
            if (homeworkGrades[i] >= 80) {
                bonusPoints += 1;
            }
        } else {
            bonusPoints += 1;
        }
    }
    if (bonusPoints < 5) {
        return false;
    } else {
        return true;
    }
}

public static double calculateDailySalary(boolean weekDay, boolean dayShift, int workedHours) {
    double baseHourSalary = 15.0;
    if (weekDay && dayShift) {
        return baseHourSalary * workedHours;
    } else {
        baseHourSalary = baseHourSalary + (baseHourSalary / 2);
        return baseHourSalary * workedHours;
    }
}
